ev = np.array([5, 4, 3, 2, 1, 0, 0, 0, 0, 0, 0, 0, 1, 2, 3, 4.]); od = np.array([0, 8, 7, 6, 5, 4, 3, 2, 0, -2, -3, -4, -5, -6, -7, -8.])
