s1050 = dft([1, 0, 5, 0]); assert np.allclose(s1050, [1.5, -1, 1.5, -1]) and abs(np.sum(s1050) - 1) < 1e-12 and abs(np.sum([1, 0, 5, 0]) - 4*s1050[0]) < 1e-12
